{
  "root": "main_stack",
  "state": {
    "ingredients": [
      {
        "item": "Active Sourdough Starter",
        "quantity": "100g",
        "notes": "fed and bubbly"
      },
      {
        "item": "Strong Bread Flour",
        "quantity": "400g",
        "notes": "e.g., white bread flour, 12-14% protein"
      },
      {
        "item": "Whole Wheat Flour (optional)",
        "quantity": "50g",
        "notes": "for added flavor and nutrition"
      },
      {
        "item": "Water (filtered, non-chlorinated)",
        "quantity": "325g",
        "notes": "72-75% hydration, adjust based on flour absorption"
      },
      {
        "item": "Fine Sea Salt",
        "quantity": "10g",
        "notes": ""
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_text",
        "intro_text",
        "context_card",
        "ingredients_card",
        "crafting_card",
        "quick_actions_stack"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Sourdough Bread: A 24-Hour Fermentation Guide",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Crafting a classic sourdough loaf involves patience and understanding of your active starter. This guide outlines the essential steps for baking a delicious, crusty sourdough bread, optimized for a 24-hour fermentation period at a consistent temperature of 20°C (68°F)."
      },
      "children": []
    },
    "context_card": {
      "type": "Card",
      "props": {},
      "children": [
        "context_header_stack",
        "context_body_text"
      ]
    },
    "context_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "context_icon",
        "context_title_text"
      ]
    },
    "context_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000005_01_1_info-circle.svg"
      },
      "children": []
    },
    "context_title_text": {
      "type": "Text",
      "props": {
        "text": "Baking Context & Assumptions",
        "variant": "h3"
      },
      "children": []
    },
    "context_body_text": {
      "type": "Text",
      "props": {
        "text": "This process assumes you are starting with an active, fed sourdough starter that reliably doubles within 4-8 hours at room temperature. The 24-hour fermentation period encompasses the bulk fermentation and final proofing stages, primarily at 20°C."
      },
      "children": []
    },
    "ingredients_card": {
      "type": "Card",
      "props": {},
      "children": [
        "ingredients_header_stack",
        "ingredients_yield_text",
        "ingredients_table"
      ]
    },
    "ingredients_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "ingredients_icon",
        "ingredients_title_text"
      ]
    },
    "ingredients_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000005_01_2_cup-straw.svg"
      },
      "children": []
    },
    "ingredients_title_text": {
      "type": "Text",
      "props": {
        "text": "Essential Sourdough Ingredients",
        "variant": "h3"
      },
      "children": []
    },
    "ingredients_yield_text": {
      "type": "Text",
      "props": {
        "text": "(Yields one ~900g loaf)"
      },
      "children": []
    },
    "ingredients_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "quantity",
            "label": "Quantity"
          },
          {
            "key": "notes",
            "label": "Notes"
          }
        ],
        "statePath": "/ingredients",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "crafting_card": {
      "type": "Card",
      "props": {},
      "children": [
        "crafting_header_stack",
        "instructions_tabs"
      ]
    },
    "crafting_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "crafting_icon",
        "crafting_title_text"
      ]
    },
    "crafting_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000005_01_3_hand-index-thumb.svg"
      },
      "children": []
    },
    "crafting_title_text": {
      "type": "Text",
      "props": {
        "text": "Step-by-Step Sourdough Crafting",
        "variant": "h3"
      },
      "children": []
    },
    "instructions_tabs": {
      "type": "Tabs",
      "props": {
        "tabs": [
          {
            "title": "Prepare Starter",
            "child": "tab_prepare_starter"
          },
          {
            "title": "Autolyse",
            "child": "tab_autolyse"
          },
          {
            "title": "Incorporate",
            "child": "tab_incorporate"
          },
          {
            "title": "Bulk Fermentation",
            "child": "tab_bulk_fermentation"
          },
          {
            "title": "Preshaping",
            "child": "tab_preshaping"
          },
          {
            "title": "Final Shaping",
            "child": "tab_final_shaping"
          },
          {
            "title": "Final Proof",
            "child": "tab_final_proof"
          },
          {
            "title": "Bake Loaf",
            "child": "tab_bake_loaf"
          }
        ]
      },
      "children": []
    },
    "tab_prepare_starter": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prepare_starter_timing",
        "prepare_starter_desc1",
        "prepare_starter_desc2"
      ]
    },
    "prepare_starter_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 4-8 hours before mixing main dough."
      },
      "children": []
    },
    "prepare_starter_desc1": {
      "type": "Text",
      "props": {
        "text": "Ensure your starter is fed and very active. It should have doubled or tripled in size and be full of bubbles."
      },
      "children": []
    },
    "prepare_starter_desc2": {
      "type": "Text",
      "props": {
        "text": "A good float test (a small spoonful floats in water) indicates readiness."
      },
      "children": []
    },
    "tab_autolyse": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "autolyse_timing",
        "autolyse_desc1",
        "autolyse_desc2"
      ]
    },
    "autolyse_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 30-60 minutes"
      },
      "children": []
    },
    "autolyse_desc1": {
      "type": "Text",
      "props": {
        "text": "In a large bowl, combine the bread flour, whole wheat flour (if using), and water. Mix until no dry spots remain and a shaggy dough forms."
      },
      "children": []
    },
    "autolyse_desc2": {
      "type": "Text",
      "props": {
        "text": "Cover the bowl and let it rest at 20°C. This allows the flour to fully hydrate and gluten development to begin naturally."
      },
      "children": []
    },
    "tab_incorporate": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "incorporate_timing",
        "incorporate_desc1",
        "incorporate_desc2",
        "incorporate_desc3"
      ]
    },
    "incorporate_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 15-20 minutes"
      },
      "children": []
    },
    "incorporate_desc1": {
      "type": "Text",
      "props": {
        "text": "Add the active sourdough starter and salt to the autolysed dough."
      },
      "children": []
    },
    "incorporate_desc2": {
      "type": "Text",
      "props": {
        "text": "Gently mix by hand, squeezing and folding the dough until the starter and salt are fully incorporated and the dough feels cohesive."
      },
      "children": []
    },
    "incorporate_desc3": {
      "type": "Text",
      "props": {
        "text": "Cover the bowl."
      },
      "children": []
    },
    "tab_bulk_fermentation": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bulk_fermentation_timing",
        "bulk_fermentation_desc1",
        "bulk_fermentation_desc2",
        "bulk_fermentation_desc3",
        "bulk_fermentation_desc4",
        "bulk_fermentation_desc5"
      ]
    },
    "bulk_fermentation_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: ~18-20 hours at 20°C (including active folding period)"
      },
      "children": []
    },
    "bulk_fermentation_desc1": {
      "type": "Text",
      "props": {
        "text": "This is the longest stage where flavor develops and the dough builds strength."
      },
      "children": []
    },
    "bulk_fermentation_desc2": {
      "type": "Text",
      "props": {
        "text": "First 2-3 hours: Perform 3-4 sets of \"stretch and folds\" every 30-45 minutes."
      },
      "children": []
    },
    "bulk_fermentation_desc3": {
      "type": "Text",
      "props": {
        "text": "With wet hands, gently stretch a portion of the dough up and fold it over itself. Rotate the bowl and repeat 3-4 times until all sides are folded."
      },
      "children": []
    },
    "bulk_fermentation_desc4": {
      "type": "Text",
      "props": {
        "text": "Remaining time: After the active folding period, cover the bowl and let the dough rest undisturbed at 20°C."
      },
      "children": []
    },
    "bulk_fermentation_desc5": {
      "type": "Text",
      "props": {
        "text": "The dough should visibly increase in volume (around 50-75% rise) and feel airy and jiggly. This long, slow fermentation develops complex flavors."
      },
      "children": []
    },
    "tab_preshaping": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "preshaping_timing",
        "preshaping_desc1",
        "preshaping_desc2",
        "preshaping_desc3"
      ]
    },
    "preshaping_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 20-30 minutes"
      },
      "children": []
    },
    "preshaping_desc1": {
      "type": "Text",
      "props": {
        "text": "Gently tip the dough onto a lightly floured surface."
      },
      "children": []
    },
    "preshaping_desc2": {
      "type": "Text",
      "props": {
        "text": "Carefully form the dough into a loose round or rectangle, using a dough scraper if needed, without degassing it too much."
      },
      "children": []
    },
    "preshaping_desc3": {
      "type": "Text",
      "props": {
        "text": "Cover with a tea towel and let it rest. This helps the gluten relax for final shaping."
      },
      "children": []
    },
    "tab_final_shaping": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "final_shaping_timing",
        "final_shaping_desc1",
        "final_shaping_desc2",
        "final_shaping_desc3"
      ]
    },
    "final_shaping_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 10-15 minutes"
      },
      "children": []
    },
    "final_shaping_desc1": {
      "type": "Text",
      "props": {
        "text": "Lightly flour your work surface again. Gently flip the dough over."
      },
      "children": []
    },
    "final_shaping_desc2": {
      "type": "Text",
      "props": {
        "text": "Shape the dough into your desired final form (boule or batard). Aim to create surface tension by folding and tucking the dough to create a tight \"skin.\""
      },
      "children": []
    },
    "final_shaping_desc3": {
      "type": "Text",
      "props": {
        "text": "Place the shaped dough seam-side up into a floured banneton (proofing basket) or a bowl lined with a floured cloth."
      },
      "children": []
    },
    "tab_final_proof": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "final_proof_timing",
        "final_proof_desc1",
        "final_proof_desc2",
        "final_proof_desc3",
        "final_proof_desc4"
      ]
    },
    "final_proof_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: 2-4 hours at 20°C OR 8-12 hours in the refrigerator (4°C)"
      },
      "children": []
    },
    "final_proof_desc1": {
      "type": "Text",
      "props": {
        "text": "For a 24-hour total fermentation, you can either:"
      },
      "children": []
    },
    "final_proof_desc2": {
      "type": "Text",
      "props": {
        "text": "Room Temperature Proof: Cover the banneton and let it proof at 20°C for 2-4 hours until it passes the \"poke test\" (a gentle poke leaves a slow rebound)."
      },
      "children": []
    },
    "final_proof_desc3": {
      "type": "Text",
      "props": {
        "text": "Cold Proof (Recommended for convenience & flavor): Cover the banneton and place it in the refrigerator for 8-12 hours (or up to 24 hours)."
      },
      "children": []
    },
    "final_proof_desc4": {
      "type": "Text",
      "props": {
        "text": "This deepens flavor and makes the dough easier to handle."
      },
      "children": []
    },
    "tab_bake_loaf": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bake_loaf_timing",
        "bake_loaf_desc1",
        "bake_loaf_desc2",
        "bake_loaf_desc3",
        "bake_loaf_desc4",
        "bake_loaf_desc5",
        "bake_loaf_desc6"
      ]
    },
    "bake_loaf_timing": {
      "type": "Text",
      "props": {
        "text": "Timing: ~45-50 minutes"
      },
      "children": []
    },
    "bake_loaf_desc1": {
      "type": "Text",
      "props": {
        "text": "Preheat: Place a Dutch oven (with lid) in your oven and preheat to 230-245°C (450-475°F) for at least 30-45 minutes."
      },
      "children": []
    },
    "bake_loaf_desc2": {
      "type": "Text",
      "props": {
        "text": "Score: Carefully remove the hot Dutch oven. Gently invert the cold-proofed dough into it. Score the top of the dough with a sharp blade."
      },
      "children": []
    },
    "bake_loaf_desc3": {
      "type": "Text",
      "props": {
        "text": "Covered Bake: Bake with the lid on for 20-25 minutes. This traps steam, allowing for maximum oven spring."
      },
      "children": []
    },
    "bake_loaf_desc4": {
      "type": "Text",
      "props": {
        "text": "Uncovered Bake: Remove the lid and bake for another 25-30 minutes, or until the crust is deep golden brown and the internal temperature reaches 96-99°C (205-210°F)."
      },
      "children": []
    },
    "bake_loaf_desc5": {
      "type": "Text",
      "props": {
        "text": "Cool: Transfer the bread to a wire rack and cool completely for at least 1-2 hours before slicing."
      },
      "children": []
    },
    "bake_loaf_desc6": {
      "type": "Text",
      "props": {
        "text": "This is crucial for texture and flavor."
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_title",
        "button_starter_guide",
        "button_more_recipes"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "button_starter_guide": {
      "type": "Button",
      "props": {
        "label": "Starter Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.theperfectloaf.com/sourdough-starter-maintenance-guide/"
          }
        }
      },
      "children": []
    },
    "button_more_recipes": {
      "type": "Button",
      "props": {
        "label": "More Recipes"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.kingarthurbaking.com/recipes/sourdough-recipes"
          }
        }
      },
      "children": []
    }
  }
}
